package com.chromascape.web.debug.tickdebugger.entity;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * JPA entity for storing timeline markers.
 *
 * <p>Markers can be auto-generated from events (errors, damage, deaths) or manually created by
 * users for navigation during replay.
 */
@Entity
@Table(
    name = "timeline_markers",
    indexes = {@Index(name = "idx_timeline_markers_session_tick", columnList = "session_id, tick")})
public class TimelineMarker {

  @Id
  @GeneratedValue(strategy = GenerationType.IDENTITY)
  private Long id;

  /** The debug session this marker belongs to. */
  @Column(name = "session_id", nullable = false, length = 100)
  private String sessionId;

  /** The game tick number this marker points to. */
  @Column(nullable = false)
  private Long tick;

  /**
   * Type of marker (e.g., "ERROR", "DAMAGE", "PRAYER", "EAT", "SPEC", "KILL", "DEATH", "LEVEL_UP",
   * "MANUAL").
   */
  @Column(name = "marker_type", nullable = false, length = 50)
  private String markerType;

  /** Severity level for color-coding (e.g., "Error", "Warn", "Info", "Success"). */
  @Column(length = 20)
  private String severity;

  /** Short label displayed on the marker. */
  @Column(length = 255)
  private String label;

  /** Optional detailed description. */
  @Column(columnDefinition = "TEXT")
  private String description;

  /** Optional reference to a log entry that triggered this marker. */
  @Column private Long logId;

  /** True if this marker was auto-generated, false if manually created. */
  @Column(name = "is_auto_generated", nullable = false)
  private Boolean isAutoGenerated;

  /** When this marker was created. */
  @Column(nullable = false)
  private LocalDateTime createdAt;

  /** Default constructor required by JPA. */
  public TimelineMarker() {
    this.isAutoGenerated = true;
    this.createdAt = LocalDateTime.now();
  }

  /** Constructor for creating timeline markers. */
  public TimelineMarker(String sessionId, Long tick, String markerType, String label) {
    this();
    this.sessionId = sessionId;
    this.tick = tick;
    this.markerType = markerType;
    this.label = label;
  }

  // Getters and Setters

  public Long getId() {
    return id;
  }

  public void setId(Long id) {
    this.id = id;
  }

  public String getSessionId() {
    return sessionId;
  }

  public void setSessionId(String sessionId) {
    this.sessionId = sessionId;
  }

  public Long getTick() {
    return tick;
  }

  public void setTick(Long tick) {
    this.tick = tick;
  }

  public String getMarkerType() {
    return markerType;
  }

  public void setMarkerType(String markerType) {
    this.markerType = markerType;
  }

  public String getSeverity() {
    return severity;
  }

  public void setSeverity(String severity) {
    this.severity = severity;
  }

  public String getLabel() {
    return label;
  }

  public void setLabel(String label) {
    this.label = label;
  }

  public String getDescription() {
    return description;
  }

  public void setDescription(String description) {
    this.description = description;
  }

  public Long getLogId() {
    return logId;
  }

  public void setLogId(Long logId) {
    this.logId = logId;
  }

  public Boolean getIsAutoGenerated() {
    return isAutoGenerated;
  }

  public void setIsAutoGenerated(Boolean isAutoGenerated) {
    this.isAutoGenerated = isAutoGenerated;
  }

  public LocalDateTime getCreatedAt() {
    return createdAt;
  }

  public void setCreatedAt(LocalDateTime createdAt) {
    this.createdAt = createdAt;
  }

  /** Returns true if this marker is an error (for color coding). */
  public boolean isError() {
    return "ERROR".equalsIgnoreCase(markerType) || "Error".equalsIgnoreCase(severity);
  }

  /** Returns true if this marker is a warning or higher. */
  public boolean isWarningOrHigher() {
    return "ERROR".equalsIgnoreCase(markerType)
        || "DAMAGE".equalsIgnoreCase(markerType)
        || "DEATH".equalsIgnoreCase(markerType);
  }
}
